    final size = p.size.name;
    for (final state in statePrecedence) {
      if (!_holds(state, p, s)) continue;
      final hit =
          cells['$cell|combined|$size|$combo|$state'] ??
          cells['$cell|appearance|$combo|$state'];
      if (hit != null) return hit;
    }
    return cells['$cell|combined|$size|$combo|default'] ??
        cells['$cell|appearance|$combo|default'] ??
        cells['$cell|size|$size'] ??
        cells['$cell|base'];
  }

  static Color color(
    SolarTheme t,
    String cell,
    SolarNumberInputProps p,
    Set<WidgetState> s,
  ) {
    final c = t.colors;
    return switch (lookup(cell, p, s)) {
      'none' => Colors.transparent,
      't:color.border.disabled' => c.borderDisabled,
      't:color.border.feedback.danger.strong' => c.borderFeedbackDangerStrong,
      't:color.border.feedback.focus.strong' => c.borderFeedbackFocusStrong,
      't:color.border.medium' => c.borderMedium,
      't:color.border.subtle' => c.borderSubtle,
      't:color.icon.disabled' => c.iconDisabled,
      't:color.icon.primary' => c.iconPrimary,
      't:color.surface.background' => c.surfaceBackground,
      't:color.surface.base' => c.surfaceBase,
      't:color.text.disabled' => c.textDisabled,
      't:color.text.feedback.danger' => c.textFeedbackDanger,
      't:color.text.feedback.info' => c.textFeedbackInfo,
      't:color.text.primary' => c.textPrimary,
      't:color.text.secondary' => c.textSecondary,
      final v => throw StateError('$cell: no colour for $v'),
    };
  }

  static List<BoxShadow> shadow(
    SolarTheme t,
    String cell,
    SolarNumberInputProps p,
    Set<WidgetState> s,
  ) => switch (lookup(cell, p, s)) {
    'none' || null => const <BoxShadow>[],
    't:shadow.control' => t.shadows.control,
    't:shadow.danger' => t.shadows.danger,
    't:shadow.focus.default' => t.shadows.focusDefault,
    final v => throw StateError('$cell: no shadow for $v'),
  };

  /// A length in logical pixels, or null where the IR says the layer hugs its content.
  static double? dimension(
    String cell,
    SolarNumberInputProps p,
    Set<WidgetState> s,
  ) {
    final v = lookup(cell, p, s);
    if (v == null || v == 'k:HUG') return null;
    if (v == 'k:FILL') return double.infinity;
    if (v.startsWith('px:')) return double.parse(v.substring(3));
    return switch (v) {
      't:border.default' => SolarBorder.$default,
      't:icon.md' => SolarIconSize.md,
      't:icon.sm' => SolarIconSize.sm,
      't:icon.xs' => SolarIconSize.xs,
      't:inset.2xs' => SolarInset.$2xs,
      't:inset.md' => SolarInset.md,
      't:inset.none' => SolarInset.none,
      't:inset.sm' => SolarInset.sm,
      't:inset.xs' => SolarInset.xs,
      't:radius.control' => SolarRadius.control,
      't:stack.none' => SolarStack.none,
      't:stack.xs' => SolarStack.xs,
      _ => throw StateError('$cell: no length for $v'),
    };
  }

  static TextStyle? textStyle(
    SolarTheme t,
    String cell,
    SolarNumberInputProps p,
    Set<WidgetState> s,
  ) => switch (lookup(cell, p, s)) {
    'none' || null => null,
    't:typography.body.md.medium' => t.typography.bodyMdMedium,
    't:typography.body.sm.medium' => t.typography.bodySmMedium,
    't:typography.helper.md' => t.typography.helperMd,
    't:typography.helper.sm' => t.typography.helperSm,
    't:typography.label.md' => t.typography.labelMd,
    't:typography.label.sm' => t.typography.labelSm,
    final v => throw StateError('$cell: no text style for $v'),
  };

  /// Whether a layer is drawn: the shell reads this, the style does not.
  static bool present(
    String layer,
    SolarNumberInputProps p,
    Set<WidgetState> s,
  ) => lookup('$layer.present', p, s) != 'b:false';
}
